## Part 2: Designing the Task Model

### The Task Class

Let's create a proper `Task` class with validation:

```python
from datetime import datetime
from uuid import uuid4


class Task:
    """Represents a single task in our management system."""

    VALID_PRIORITIES = range(1, 6)  # 1 through 5

    def __init__(self, name, priority=3, due_date=None, tags=None):
        self.id = str(uuid4())
        self.name = name
        self.priority = priority
        self.due_date = due_date
        self.tags = tags or []
        self.completed = False
        self.created_at = datetime.now()

    def mark_complete(self):
        self.completed = True

    def mark_incomplete(self):
        self.completed = False

    def add_tag(self, tag):
        if tag not in self.tags:
            self.tags.append(tag)

    def remove_tag(self, tag):
        if tag in self.tags:
            self.tags.remove(tag)

    def is_overdue(self):
        if self.due_date is None or self.completed:
            return False
        return datetime.now() > self.due_date

    def __repr__(self):
        status = "✓" if self.completed else "○"
        return f"Task({status} {self.name!r}, priority={self.priority})"
```

### Adding Validation

Raw attributes can accept invalid values. Let's use properties to enforce rules:

```python
class Task:
    VALID_PRIORITIES = range(1, 6)

    def __init__(self, name, priority=3, due_date=None, tags=None):
        self.id = str(uuid4())
        self.name = name          # Uses the property setter
        self.priority = priority  # Uses the property setter
        self.due_date = due_date
        self.tags = tags or []
        self.completed = False
        self.created_at = datetime.now()

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        if not isinstance(value, str) or not value.strip():
            raise ValueError("Task name must be a non-empty string")
        self._name = value.strip()

    @property
    def priority(self):
        return self._priority

    @priority.setter
    def priority(self, value):
        if value not in self.VALID_PRIORITIES:
            raise ValueError(f"Priority must be 1-5, got {value}")
        self._priority = value
```

